CREATE TABLE "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);


CREATE TABLE "Chunks" (
    "ID" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" text NOT NULL,
    "TemplateSource" text,
    "TemplatePath" text NOT NULL,
    CONSTRAINT "PK_Chunks" PRIMARY KEY ("ID")
);

CREATE TABLE "Images" (
    "ID" integer GENERATED BY DEFAULT AS IDENTITY,
    "ShortPath" text COLLATE "C" NOT NULL,
    "ShortPathHash" integer NOT NULL,
    "FullName" text NOT NULL,
    "Width" bigint NOT NULL,
    "Height" bigint NOT NULL,
    CONSTRAINT "PK_Images" PRIMARY KEY ("ID"),
    CONSTRAINT "CK_Images_Height_UInt32" CHECK ("Height" BETWEEN 0 AND 4294967295),
    CONSTRAINT "CK_Images_Width_UInt32" CHECK ("Width" BETWEEN 0 AND 4294967295)
);

CREATE TABLE "Redirections" (
    "ID" integer GENERATED BY DEFAULT AS IDENTITY,
    "RequestPathHash" integer NOT NULL,
    "RequestPath" text COLLATE "C" NOT NULL,
    "RedirectionPath" text NOT NULL,
    CONSTRAINT "PK_Redirections" PRIMARY KEY ("ID")
);

CREATE TABLE "SecurityInstallation" (
    "ID" integer NOT NULL,
    "SchemaVersion" integer NOT NULL,
    "InitializedUtc" timestamp(6) with time zone NOT NULL,
    "LegacyPasswordResetCompleted" boolean NOT NULL,
    CONSTRAINT "PK_SecurityInstallation" PRIMARY KEY ("ID")
);

CREATE TABLE "SynonymsForStrings" (
    "ID" integer GENERATED BY DEFAULT AS IDENTITY,
    "String" text COLLATE "C" NOT NULL,
    "Synonym" text COLLATE "C" NOT NULL,
    CONSTRAINT "PK_SynonymsForStrings" PRIMARY KEY ("ID")
);

CREATE TABLE "Templates" (
    "ID" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" text NOT NULL,
    "TemplateSource" text,
    "TemplatePath" text NOT NULL,
    CONSTRAINT "PK_Templates" PRIMARY KEY ("ID")
);

CREATE TABLE "UserTypes" (
    "ID" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" text NOT NULL,
    "AccessLevel" integer NOT NULL,
    CONSTRAINT "PK_UserTypes" PRIMARY KEY ("ID"),
    CONSTRAINT "CK_UserTypes_AccessLevel" CHECK ("AccessLevel" BETWEEN 1 AND 5)
);

CREATE TABLE "Visitors" (
    "ID" integer GENERATED BY DEFAULT AS IDENTITY,
    "IPAdress" text COLLATE "C" NOT NULL,
    "IPStringHash" integer NOT NULL,
    "FirstVisit" timestamp(6) without time zone NOT NULL,
    "LastVisit" timestamp(6) without time zone NOT NULL,
    CONSTRAINT "PK_Visitors" PRIMARY KEY ("ID")
);

CREATE TABLE "UsualPages" (
    "ID" integer GENERATED BY DEFAULT AS IDENTITY,
    "PreviousPageID" integer,
    "RequestPathHash" integer NOT NULL,
    "Title" text NOT NULL,
    "PageName" text NOT NULL,
    "Alias" text NOT NULL,
    "RequestPath" text COLLATE "C" NOT NULL,
    "BreadcrumbsHtml" text,
    "TemplateId" integer,
    "Content" text,
    "Published" boolean NOT NULL,
    "PageDescription" text,
    "PageKeywords" text,
    "IsIndex" boolean NOT NULL,
    "IsFollow" boolean NOT NULL,
    CONSTRAINT "PK_UsualPages" PRIMARY KEY ("ID"),
    CONSTRAINT "FK_UsualPages_Templates_TemplateId" FOREIGN KEY ("TemplateId") REFERENCES "Templates" ("ID"),
    CONSTRAINT "FK_UsualPages_UsualPages_PreviousPageID" FOREIGN KEY ("PreviousPageID") REFERENCES "UsualPages" ("ID")
);

CREATE TABLE "Users" (
    "ID" integer GENERATED BY DEFAULT AS IDENTITY,
    "Login" text COLLATE "C" NOT NULL,
    "Password" text NOT NULL,
    "RequirePasswordChange" boolean NOT NULL,
    "Email" text,
    "IdleTime" bigint NOT NULL,
    "UserTypeID" integer NOT NULL,
    CONSTRAINT "PK_Users" PRIMARY KEY ("ID"),
    CONSTRAINT "CK_Users_IdleTime" CHECK ("IdleTime" BETWEEN 10 AND 10080),
    CONSTRAINT "FK_Users_UserTypes_UserTypeID" FOREIGN KEY ("UserTypeID") REFERENCES "UserTypes" ("ID") ON DELETE CASCADE
);

CREATE TABLE "VisitedPages" (
    "ID" integer GENERATED BY DEFAULT AS IDENTITY,
    "VisitorId" integer NOT NULL,
    "VisitedPageId" integer NOT NULL,
    "PageType" integer NOT NULL,
    CONSTRAINT "PK_VisitedPages" PRIMARY KEY ("ID"),
    CONSTRAINT "CK_VisitedPages_PageType" CHECK ("PageType" BETWEEN 1 AND 3),
    CONSTRAINT "FK_VisitedPages_Visitors_VisitorId" FOREIGN KEY ("VisitorId") REFERENCES "Visitors" ("ID") ON DELETE CASCADE
);

CREATE TABLE "CategoryPages" (
    "ID" integer GENERATED BY DEFAULT AS IDENTITY,
    "ProductsCount" bigint NOT NULL,
    "PreviousPageID" integer,
    "LastProductTemplateID" integer,
    "RequestPathHash" integer NOT NULL,
    "Title" text NOT NULL,
    "PageName" text NOT NULL,
    "Alias" text NOT NULL,
    "RequestPath" text COLLATE "C" NOT NULL,
    "BreadcrumbsHtml" text,
    "TemplateId" integer,
    "Content" text,
    "Published" boolean NOT NULL,
    "PageDescription" text,
    "PageKeywords" text,
    "IsIndex" boolean NOT NULL,
    "IsFollow" boolean NOT NULL,
    CONSTRAINT "PK_CategoryPages" PRIMARY KEY ("ID"),
    CONSTRAINT "CK_CategoryPages_ProductsCount_UInt32" CHECK ("ProductsCount" BETWEEN 0 AND 4294967295),
    CONSTRAINT "FK_CategoryPages_Templates_LastProductTemplateID" FOREIGN KEY ("LastProductTemplateID") REFERENCES "Templates" ("ID"),
    CONSTRAINT "FK_CategoryPages_Templates_TemplateId" FOREIGN KEY ("TemplateId") REFERENCES "Templates" ("ID"),
    CONSTRAINT "FK_CategoryPages_UsualPages_PreviousPageID" FOREIGN KEY ("PreviousPageID") REFERENCES "UsualPages" ("ID")
);

CREATE TABLE "AdminPanelLogs" (
    "ID" integer GENERATED BY DEFAULT AS IDENTITY,
    "UserId" integer NOT NULL,
    "Time" timestamp(6) without time zone NOT NULL,
    "Info" text NOT NULL,
    CONSTRAINT "PK_AdminPanelLogs" PRIMARY KEY ("ID"),
    CONSTRAINT "FK_AdminPanelLogs_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("ID") ON DELETE CASCADE
);

CREATE TABLE "ConnectedUsers" (
    "ID" integer GENERATED BY DEFAULT AS IDENTITY,
    "TokenHash" character varying(64) COLLATE "C" NOT NULL,
    "LastActionUtc" timestamp(6) with time zone NOT NULL,
    "IPAdress" character varying(45) NOT NULL,
    "UserAgent" character varying(255) NOT NULL,
    "UserID" integer NOT NULL,
    CONSTRAINT "PK_ConnectedUsers" PRIMARY KEY ("ID"),
    CONSTRAINT "CK_ConnectedUsers_TokenHash" CHECK ("TokenHash" ~ '^[0-9a-f]{64}$'),
    CONSTRAINT "FK_ConnectedUsers_Users_UserID" FOREIGN KEY ("UserID") REFERENCES "Users" ("ID") ON DELETE CASCADE
);

CREATE TABLE "ProductPages" (
    "ID" integer GENERATED BY DEFAULT AS IDENTITY,
    "Price" bigint NOT NULL,
    "OldPrice" bigint NOT NULL,
    "Barcode" text,
    "ShortDescription" text,
    "SpecialProduct" boolean NOT NULL,
    "LastUpdate" timestamp(6) without time zone NOT NULL,
    "PreviousPageID" integer NOT NULL,
    "RequestPathHash" integer NOT NULL,
    "Title" text NOT NULL,
    "PageName" text NOT NULL,
    "Alias" text NOT NULL,
    "RequestPath" text COLLATE "C" NOT NULL,
    "BreadcrumbsHtml" text,
    "TemplateId" integer,
    "Content" text,
    "Published" boolean NOT NULL,
    "PageDescription" text,
    "PageKeywords" text,
    "IsIndex" boolean NOT NULL,
    "IsFollow" boolean NOT NULL,
    CONSTRAINT "PK_ProductPages" PRIMARY KEY ("ID"),
    CONSTRAINT "CK_ProductPages_OldPrice_UInt32" CHECK ("OldPrice" BETWEEN 0 AND 4294967295),
    CONSTRAINT "CK_ProductPages_Price_UInt32" CHECK ("Price" BETWEEN 0 AND 4294967295),
    CONSTRAINT "FK_ProductPages_CategoryPages_PreviousPageID" FOREIGN KEY ("PreviousPageID") REFERENCES "CategoryPages" ("ID") ON DELETE CASCADE,
    CONSTRAINT "FK_ProductPages_Templates_TemplateId" FOREIGN KEY ("TemplateId") REFERENCES "Templates" ("ID")
);

